def list_to_text(items):
    # fewer than three items need no commas
    if len(items) < 3:
        return ' and '.join(items)
    # join all but the last, then add 'and' and the last
    return ', '.join(items[:-1]) + ', and ' + items[-1]
tests = [['a', 'b', 'c'], ['x', 'y'], ['z'], []]
for t in tests:
    print(repr(list_to_text(t)))
